namespace Shop.Api.Apis;

using Microsoft.EntityFrameworkCore;

/// <summary> Generated by API_Registration: the database and one route group per table, so Program.cs lists nothing. </summary>
public static class ApiRegistration
{
    public static IServiceCollection AddGeneratedDbContext(this IServiceCollection services, IConfiguration configuration) =>
        services.AddDbContext<ShopContext>(options => ShopContext.UseProvider(options, configuration.GetConnectionString("DbConnectionString")));

    public static void RegisterGeneratedApis(this WebApplication app)
    {
        new CustomerApi().Register(app);
        new ProductApi().Register(app);
        new SalesOrderApi().Register(app);

        new CustomerSearchApi<Customer>().Register(app);
        new SalesOrderSearchApi<SalesOrder>().Register(app);

        DashboardApi.Register(app);
    }
}
